def first[T](items: list[T]) -> T:
    return items[0]


print(first([1, 2]), first(["a", "b"]))

def find_user(uid: int) -> str | None:
    users = {1: "Ada"}
    return users.get(uid)


user = find_user(2)
print(user)
print(user is None)

from typing import Protocol


class Speaker(Protocol):
    def speak(self) -> str: ...


class Dog:
    def speak(self) -> str:
        return "汪"


def announce(s: Speaker) -> str:
    return f"它说：{s.speak()}"


print(announce(Dog()))
